mapper.select:
SELECT id, creator_id, title, description, start_date, end_date, target_count, challenge_type, created_at
FROM challenges
WHERE id = #{id}

SELECT COUNT(1)
FROM challenge_participants
WHERE challenge_id = #{challengeId}
  AND user_id      = #{userId}

mapper.delete:
DELETE FROM challenge_participants
WHERE challenge_id = #{challengeId}
  AND user_id      = #{userId}

DELETE FROM challenges
WHERE id         = #{id}
  AND creator_id = #{creatorId}
